-- ============================================================================
-- LEGEND OF THE GREEN DRAGON (NB-Core / v1.1.x - v2.0.9+nb)
-- DUNGEON CRAWLER CARL ENHANCED PET BISCUIT MENAGERIE (`mounts` TABLE)
-- Target Repository: https://github.com/machineh3d/lotgd-dcc
-- Lore Reference: https://dungeon-crawler-carl.fandom.com/wiki/Category:Pets
-- ============================================================================
-- NOTES:
-- 1. All `mountbuff` payloads are generated with exact UTF-8 byte lengths for
--    strict PHP 8.4/8.5 `unserialize()` compatibility.
-- 2. If your LotGD tables use a prefix (e.g. `lotgd_mounts`), add the prefix
--    before running:
--    mysql -u root -p lotgd < lotgd_dcc_mounts.sql
-- 3. Flush your `datacache/` directory after importing.
-- ============================================================================

SET NAMES utf8mb4;
START TRANSACTION;

TRUNCATE TABLE `mounts`;

INSERT INTO `mounts` (
    `mountid`, `mountname`, `mountdesc`, `mountcategory`, `mountbuff`,
    `mountcostgems`, `mountcostgold`, `mountactive`, `mountfeedcost`,
    `mountforestfights`, `newday`, `recharge`, `partrecharge`, `mountdkcost`
) VALUES
(1, 'Syndicate Cleaner Bot', 'A chirping circular maintenance vacuum that follows you through the Safe Room andDungeon corridors, cheerfully scrubbing goblin viscera off your bare feet while tripping nearby mobs.', 'Dungeon Constructs', 'a:12:{s:4:"name";s:32:"`7Syndicate Cleaner Bot Assist`0";s:8:"roundmsg";s:67:"`7Your Cleaner Bot aggressively vacuums around {badguy}''s ankles!`0";s:7:"wearoff";s:67:"Your Cleaner Bot''s battery runs low and it docks in your inventory.";s:9:"effectmsg";s:73:"`7The Cleaner Bot rams {badguy}''s shins for `^{damage}`7 bumper damage!`0";s:14:"effectnodmgmsg";s:64:"`7The Cleaner Bot beeps indignantly as {badguy} steps over it.`0";s:6:"rounds";i:15;s:6:"atkmod";d:1.05;s:6:"defmod";d:1.05;s:11:"minioncount";i:1;s:15:"minbadguydamage";i:1;s:15:"maxbadguydamage";i:3;s:6:"schema";s:5:"mount";}', 0, 300, 1, 15, 0, '`2Your `7Syndicate Cleaner Bot`2 beeps cheerfully and polishes the dried blood off your ankles.`0', '`2You empty the Cleaner Bot''s bio-filter canister and recharge its battery cell.`0', '`2You top off the Cleaner Bot''s battery charge as best you can.`0', 0),
(2, 'Sir Rendlegore (Rend the Tummy-Acher)', 'A round, rubbery, meatball-shaped dungeon creature with stubby legs and a mouth full of razor teeth. He waddles happily beside you and takes enthusiastic chunks out of your enemies'' kneecaps.', 'Enhanced Pets', 'a:12:{s:4:"name";s:31:"`4Sir Rendlegore''s Ankle-Bite`0";s:8:"roundmsg";s:69:"`4Rend bounces across the corridor floor like a rabid bowling ball!`0";s:7:"wearoff";s:40:"Rend curls up into a round meatball nap.";s:9:"effectmsg";s:64:"`4Rend latches onto {badguy} for `^{damage}`4 chomping damage!`0";s:14:"effectnodmgmsg";s:47:"`4Rend snaps his jaws at {badguy} but misses!`0";s:6:"rounds";i:25;s:6:"atkmod";d:1.1;s:6:"defmod";d:1.12;s:11:"minioncount";i:1;s:15:"minbadguydamage";i:2;s:15:"maxbadguydamage";i:7;s:6:"schema";s:5:"mount";}', 2, 1200, 1, 45, 1, '`2`4Sir Rendlegore`2 bounces out of his pet carrier like an overexcited meatball, granting you `@+1 Floor Encounter`2!`0', '`2You toss Rend a pile of fresh goblin gristle, restoring him to peak chomping energy.`0', '`2Rend snacks on a leftover ration bar and burps contentedly.`0', 0),
(3, 'Bautista''s Kimaris Plush Minion', 'A collectible Beanie-Baby-style Kimaris plush figure from Daniel Bautista''s pouch. When thrown into combat, it expands into a ferocious summoned demon warrior.', 'Summoned Familiars', 'a:12:{s:4:"name";s:34:"`5Summoned Kimaris Plush Warrior`0";s:8:"roundmsg";s:61:"`5Your summoned Kimaris plush minion charges into the fray!`0";s:7:"wearoff";s:58:"The Kimaris warrior pops back into a harmless stuffed toy.";s:9:"effectmsg";s:78:"`5The summoned Kimaris slashes {badguy} for `^{damage}`5 demon-plush damage!`0";s:14:"effectnodmgmsg";s:58:"`5The Kimaris minion''s stuffing absorbs a glancing blow.`0";s:6:"rounds";i:30;s:6:"atkmod";d:1.15;s:6:"defmod";d:1.15;s:11:"minioncount";i:1;s:15:"minbadguydamage";i:4;s:15:"maxbadguydamage";i:12;s:6:"schema";s:5:"mount";}', 5, 2800, 1, 90, 1, '`2Your `5Kimaris Plush Figure`2 hums with stored summoning magic (`@+1 Floor Encounter`2)!`0', '`2You stitch up a torn seam on the Kimaris plushie and re-infuse its tag.`0', '`2You brush the dust off the Kimaris plushie''s collectible tag.`0', 0),
(4, 'Lucia Mar''s Enhanced War-Rottweiler (Gustavo 3)', 'An Enhanced Pet Biscuit survivor bred for pure aggression. Wearing spiked collar plating, this massive Rottweiler tears through corridor packs before they can reach your throat.', 'Enhanced Pets', 'a:12:{s:4:"name";s:36:"`^Enhanced War-Rottweiler Ferocity`0";s:8:"roundmsg";s:63:"`^Your War-Rottweiler circles {badguy} with glowing red eyes!`0";s:7:"wearoff";s:49:"Your War-Rottweiler retreats to guard your flank.";s:9:"effectmsg";s:75:"`^The Enhanced Rottweiler mauls {badguy} for `4{damage}`^ tearing damage!`0";s:14:"effectnodmgmsg";s:69:"`^The Rottweiler''s spiked collar deflects {badguy}''s counterattack!`0";s:6:"rounds";i:40;s:6:"atkmod";d:1.22;s:6:"defmod";d:1.18;s:11:"minioncount";i:2;s:15:"minbadguydamage";i:6;s:15:"maxbadguydamage";i:16;s:6:"schema";s:5:"mount";}', 10, 5500, 1, 160, 2, '`2`^Gustavo 3`2 lets out a bone-rattling bark at the Safe Room door, eager for blood (`@+2 Floor Encounters`2)!`0', '`2You feed Gustavo 3 a prime cut of ribeye steak, fully restoring his stamina.`0', '`2Gustavo 3 wolfs down a bowl of enhanced kibble.`0', 1),
(5, 'Mongo the Juvenile Mongoliensis Raptor', 'Princess Donut''s prized Second-Floor velociraptor companion! Covered in bright pink and red feathers, Mongo shrieks with glee and leaps face-first onto anything that moves.', 'Royal Court Companions', 'a:12:{s:4:"name";s:25:"`@Mongo''s Raptor Pounce`0";s:8:"roundmsg";s:80:"`@Mongo shrieks and leaps onto {badguy} in a blur of pink feathers and talons!`0";s:7:"wearoff";s:61:"`5"MONGO, BACK IN THE CARRIER!"`0 Mongo reluctantly retreats.";s:9:"effectmsg";s:76:"`@Mongo''s sickle claws disembowel {badguy} for `^{damage}`@ raptor damage!`0";s:14:"effectnodmgmsg";s:57:"`@Mongo hisses, appalled by {badguy}''s lack of manners!`0";s:6:"rounds";i:50;s:6:"atkmod";d:1.28;s:6:"defmod";d:1.22;s:11:"minioncount";i:1;s:15:"minbadguydamage";i:10;s:15:"maxbadguydamage";i:26;s:6:"schema";s:5:"mount";}', 18, 9500, 1, 250, 2, '`2`5"GOOD MORNING, MONGO!"`2 Your feathered raptor chirps and bounds into the corridor (`@+2 Floor Encounters`2)!`0', '`2Mongo devours a fresh basket of dungeon meat while Princess Donut brushes his feathers.`0', '`2You toss Mongo a handful of goblin jerky treats.`0', 1),
(6, 'Full-Grown Mongo (Tizheruk Fang Caps & Saddle)', 'Now large enough to ride into battle! Outfitted with Enchanted Fang Caps of the Expectorating Tizheruk and a custom Iron Tangle combat saddle, Mongo is an apex corridor predator.', 'Royal Court Companions', 'a:13:{s:4:"name";s:44:"`@Armored War-Steed Mongo (Tizheruk Fangs)`0";s:8:"roundmsg";s:84:"`@Mongo charges into {badguy} with his Enchanted Tizheruk Fang Caps dripping acid!`0";s:7:"wearoff";s:48:"Mongo pauses to shake bits of mob off his snout.";s:9:"effectmsg";s:85:"`@Mongo''s Tizheruk-capped jaws crush {badguy} for `4{damage}`@ acid-rending damage!`0";s:14:"effectnodmgmsg";s:54:"`@Mongo''s armored saddle deflects {badguy}''s strike!`0";s:6:"rounds";i:65;s:6:"atkmod";d:1.38;s:6:"defmod";d:1.3;s:7:"lifetap";d:0.1;s:11:"minioncount";i:1;s:15:"minbadguydamage";i:15;s:15:"maxbadguydamage";i:40;s:6:"schema";s:5:"mount";}', 35, 18000, 1, 400, 3, '`2`@Full-Grown Mongo`2 clicks his Tizheruk-capped fangs and stamps his talons (`@+3 Floor Encounters`2)!`0', '`2You polish Mongo''s enchanted fang caps and feed him a whole Mold Lion haunch.`0', '`2Mongo snacks on a fallen mob and sharpens his talons.`0', 3),
(7, 'Bianca the Winged Hellspawn Goat Familiar', 'Miriam Dom and Prepotente''s terrifying Legendary Pet Biscuit result: a horse-sized, six-eyed, fire-breathing demonic goat with leathery bat wings that devours bosses whole.', 'Legendary Pet Box', 'a:13:{s:4:"name";s:30:"`$Bianca''s Hellspawn Inferno`0";s:8:"roundmsg";s:70:"`$Bianca swoops down from the ceiling, bathing {badguy} in hellfire!`0";s:7:"wearoff";s:49:"Bianca lands heavily and folds her demonic wings.";s:9:"effectmsg";s:91:"`$Bianca''s hellfire breath and horns incinerate {badguy} for `^{damage}`$ demonic damage!`0";s:14:"effectnodmgmsg";s:63:"`${badguy} cowers in terror before Bianca''s six glowing eyes!`0";s:6:"rounds";i:80;s:6:"atkmod";d:1.48;s:6:"defmod";d:1.38;s:12:"badguyatkmod";d:0.85;s:11:"minioncount";i:1;s:15:"minbadguydamage";i:22;s:15:"maxbadguydamage";i:55;s:6:"schema";s:5:"mount";}', 55, 30000, 1, 650, 4, '`2`\\$Bianca the Hellspawn Familiar`2 unfurls her leathery wings and snorts brimstone (`@+4 Floor Encounters`2)!`0', '`2Prepotente hums a lullaby while Bianca devours a cauldron of alchemical sulfur.`0', '`2Bianca chews on amouthful of enchanted hell-charcoal.`0', 5),
(8, 'Clockwork Triplicate Mongo Swarm', 'Princess Donut''s ultimate Clockwork Triplicate synergy: three simultaneous mechanical-arcane Mongos with Tizheruk fang caps tearing across the battlefield in synchronized formation!', 'Legendary Pet Box', 'a:14:{s:4:"name";s:35:"`5Clockwork Triplicate Mongo Pack`0";s:8:"roundmsg";s:65:"`5All THREE Clockwork Mongos pounce on {badguy} simultaneously!`0";s:7:"wearoff";s:84:"Two of the Clockwork Triplicate Mongos shimmer and merge back into the prime raptor.";s:9:"effectmsg";s:86:"`5A synchronized raptor talon strike shreds {badguy} for `^{damage}`5 savage damage!`0";s:14:"effectnodmgmsg";s:74:"`5The triplicate raptor pack surrounds {badguy}, cutting off all escape!`0";s:6:"rounds";i:100;s:6:"atkmod";d:1.6;s:6:"defmod";d:1.45;s:12:"badguyatkmod";d:0.8;s:7:"lifetap";d:0.15;s:11:"minioncount";i:3;s:15:"minbadguydamage";i:18;s:15:"maxbadguydamage";i:45;s:6:"schema";s:5:"mount";}', 80, 45000, 1, 900, 5, '`2`5Clockwork Triplicate Engaged!`2 **Three synchronized Mongos** screech in unison (`@+5 Floor Encounters`2)!`0', '`2Mordecai tunes the clockwork gears and feeds all three Mongos a royal feast!`0', '`2You wind the triplicate clockwork springs and toss the pack a treat.`0', 6);

COMMIT;
